B=[
("temps","easy","Cold foods like yogurt and milk must be held at what temperature or below?","¿A qué temperatura o menos se deben mantener alimentos fríos como yogur y leche?",["41°F (5°C)","50°F (10°C)","60°F (16°C)","32°F only"],["41°F (5°C)","50°F (10°C)","60°F (16°C)","Solo 32°F"],"The FDA Food Code sets cold holding at 41°F or below.","El Código de Alimentos de la FDA marca 41°F o menos para mantener en frío.",FC),
("temps","easy","Hot foods like eggs and sausage must be held at what temperature or above?","¿A qué temperatura o más se deben mantener alimentos calientes como huevo y salchicha?",["135°F (57°C)","100°F (38°C)","110°F (43°C)","90°F (32°C)"],["135°F (57°C)","100°F (38°C)","110°F (43°C)","90°F (32°C)"],"Hot holding at 135°F or above keeps bacteria from growing.","Mantener a 135°F o más evita que crezcan bacterias.",FC),
("temps","med","What's the temperature 'danger zone' where bacteria grow fastest?","¿Cuál es la 'zona de peligro' de temperatura donde las bacterias crecen más rápido?",["Between 41°F and 135°F","Below 32°F","Above 200°F","Only at room temperature exactly"],["Entre 41°F y 135°F","Abajo de 32°F","Arriba de 200°F","Solo a temperatura ambiente exacta"],"Keep cold food cold and hot food hot to stay out of the danger zone.","Mantén lo frío frío y lo caliente caliente para salir de la zona de peligro.",FC),
("temps","med","Leftover sausage is being reheated for hot holding. To what temperature?","Se recalienta salchicha que sobró para mantenerla caliente. ¿A qué temperatura?",["165°F (74°C) within 2 hours","120°F","135°F after 4 hours","Just warm to the touch"],["165°F (74°C) en menos de 2 horas","120°F","135°F después de 4 horas","Solo tibia al tacto"],"The Food Code requires reheating to 165°F within 2 hours for hot holding.","El Código pide recalentar a 165°F en menos de 2 horas para mantener caliente.",FC),
("temps","hard","How should you check the temperature of food on the buffet?","¿Cómo debes revisar la temperatura de la comida en el buffet?",["With a clean, sanitized probe thermometer in the thickest part","By touching it","By looking at the steam","With a room thermostat"],["Con un termómetro de sonda limpio y desinfectado en la parte más gruesa","Tocándola","Viendo el vapor","Con el termostato del cuarto"],"Log temps on a schedule — steam doesn't mean it's hot enough.","Anota temperaturas en horario; el vapor no significa que esté bastante caliente.",FC),
("temps","hard","Cooked food must cool from 135°F to 70°F within how long?","La comida cocida debe enfriarse de 135°F a 70°F en cuánto tiempo?",["Within 2 hours","Half a day","By the next morning","There is no time limit"],["En máximo 2 horas","En medio día","Para la mañana siguiente","No hay límite de tiempo"],"Then from 70°F to 41°F within 4 more hours.","Luego de 70°F a 41°F en máximo 4 horas más.",FC),
("handwash","easy","How long should you scrub your hands when washing?","¿Cuánto tiempo debes tallarte las manos al lavártelas?",["At least 20 seconds","3 seconds","Just a rinse","1 minute of only water"],["Al menos 20 segundos","3 segundos","Solo enjuagarlas","1 minuto solo con agua"],"Soap, 20 seconds of scrubbing, rinse, and dry with a paper towel.","Jabón, 20 segundos tallando, enjuagar y secar con toalla de papel.",HW),
("handwash","easy","When must you wash your hands during breakfast service?","¿Cuándo debes lavarte las manos durante el desayuno?",["After touching trash, your face, or raw eggs, and before putting on gloves","Only at the start of shift","Only after using the restroom","Never if wearing gloves"],["Después de tocar basura, tu cara o huevo crudo, y antes de ponerte guantes","Solo al empezar el turno","Solo al ir al baño","Nunca si usas guantes"],"Gloves don't replace handwashing.","Los guantes no sustituyen el lavado de manos.",FC),
("handwash","med","Where should you wash your hands in the breakfast area?","¿Dónde debes lavarte las manos en el área de desayuno?",["At the designated handwashing sink only","In the food prep sink","In the coffee station sink","In the mop sink"],["Solo en el lavamanos designado","En la tarja de preparar comida","En la tarja de la estación de café","En la tarja de trapeador"],"Handwashing sinks are only for hands, so food sinks stay clean.","El lavamanos es solo para manos, para que las tarjas de comida sigan limpias.",FC),
("allergens","med","How many major food allergens does US law recognize?","¿Cuántos alérgenos principales reconoce la ley de EE. UU.?",["9","5","12","3"],["9","5","12","3"],"Milk, eggs, fish, shellfish, tree nuts, peanuts, wheat, soy and sesame (added 2023).","Leche, huevo, pescado, mariscos, nueces, cacahuate, trigo, soya y ajonjolí (desde 2023).",ALG),
("allergens","med","A guest asks if the muffins contain nuts. You're not sure. What do you say?","Un huésped pregunta si los muffins tienen nueces. No estás segura. ¿Qué dices?",["I'll check the package label for you","No, they're fine","Probably not","Just pick around them"],["Le reviso la etiqueta del paquete","No, no tienen","Probablemente no","Nada más quíteles lo que no quiera"],"Never guess about allergens. Check the label or say you can't confirm.","Nunca adivines con alérgenos. Revisa la etiqueta o di que no lo puedes confirmar.",ALG),
("allergens","hard","Why use a separate tongs for each buffet item?","¿Por qué usar pinzas separadas para cada alimento del buffet?",["To prevent allergen cross-contact between foods","To look fancy","Because tongs break","So guests use more"],["Para evitar el contacto cruzado de alérgenos entre alimentos","Para verse elegante","Porque las pinzas se rompen","Para que los huéspedes sirvan más"],"Sharing utensils can move nuts or wheat to an allergy-safe item.","Compartir utensilios puede pasar nueces o trigo a un alimento seguro.",ALG),
("eggs","med","Scrambled eggs cooked for immediate service must reach what internal temperature?","Los huevos revueltos para servir de inmediato deben llegar a qué temperatura interna?",["145°F (63°C) for 15 seconds","100°F","120°F","165°F for 1 minute only"],["145°F (63°C) por 15 segundos","100°F","120°F","165°F por solo 1 minuto"],"Food Code: 145°F for eggs cooked to order; 155°F if held hot.","Código de Alimentos: 145°F para huevos al momento; 155°F si se mantienen calientes.",FC),
("eggs","easy","Where should raw shell eggs be stored in the fridge?","¿Dónde se guardan los huevos crudos en el refrigerador?",["On a lower shelf, below ready-to-eat foods","On the top shelf above fruit","Next to the yogurt","At room temperature"],["En un estante de abajo, debajo de lo que está listo para comer","En el estante de arriba sobre la fruta","Junto al yogur","A temperatura ambiente"],"Raw foods go below ready-to-eat foods so drips can't contaminate them.","Lo crudo va abajo de lo listo para comer para que no gotee encima.",FC),
("labeling","med","You open a gallon of milk. What do you write on it?","Abres un galón de leche. ¿Qué le escribes?",["The open date or use-by date per policy","Your name only","The guest count","Nothing"],["La fecha en que se abrió o se debe usar según la política","Solo tu nombre","Cuántos huéspedes hay","Nada"],"Date marking keeps you from serving old food.","Marcar la fecha evita servir comida vieja.",FC),
("labeling","easy","What's the 'first in, first out' (FIFO) rule?","¿Qué es la regla de 'primero en entrar, primero en salir' (PEPS)?",["Use older stock before newer stock","Use the newest first","Throw everything out daily","Serve whatever is closest"],["Usar lo más viejo antes que lo nuevo","Usar lo más nuevo primero","Tirar todo cada día","Servir lo que esté más cerca"],"Put new deliveries behind older product.","Pon lo que llega nuevo detrás de lo que ya tenías.",FC),
("cleaning","med","What's the difference between cleaning and sanitizing a counter?","¿Cuál es la diferencia entre limpiar y desinfectar una barra?",["Cleaning removes dirt; sanitizing reduces germs to safe levels","They're the same","Sanitizing is just rinsing","Cleaning uses only sanitizer"],["Limpiar quita la suciedad; desinfectar baja los gérmenes a niveles seguros","Son lo mismo","Desinfectar es solo enjuagar","Limpiar es usar solo desinfectante"],"Clean first, then sanitize — sanitizer can't work through crumbs.","Primero limpia y luego desinfecta; el desinfectante no funciona sobre migajas.",FC),
("cleaning","med","How do you know your sanitizer bucket is the right strength?","¿Cómo sabes que tu cubeta de desinfectante tiene la concentración correcta?",["Check it with the test strips","Smell it","It looks cloudy","Add more until it burns"],["Revisarla con las tiras de prueba","Olerla","Se ve turbia","Echar más hasta que arda"],"Too weak won't kill germs; too strong can be unsafe.","Muy débil no mata gérmenes; muy fuerte puede ser peligroso.",FC),
("illness","med","You woke up with vomiting and diarrhea. What should you do about your breakfast shift?","Amaneciste con vómito y diarrea. ¿Qué haces con tu turno de desayuno?",["Tell your manager and don't work with food","Come in and wear gloves","Work but skip the eggs","Say nothing"],["Avisarle a tu gerente y no trabajar con alimentos","Ir y usar guantes","Trabajar pero no tocar huevos","No decir nada"],"Food workers with vomiting or diarrhea must be excluded to protect guests.","Quien tiene vómito o diarrea no debe manejar alimentos, para proteger a los huéspedes.",FC),
("waffle","easy","The waffle maker beeps and a kid is reaching for it. What's the best move?","La wafflera pita y un niño la quiere tocar. ¿Qué es lo mejor?",["Kindly step in, warn that it's hot, and help them","Ignore it","Yell at the kid","Unplug it for the day"],["Acercarte con amabilidad, avisar que está caliente y ayudarle","Ignorarlo","Gritarle al niño","Desconectarla todo el día"],"Waffle irons get very hot. A friendly assist prevents burns.","Las wafleras se calientan mucho. Ayudar con amabilidad evita quemaduras.",BP),
("buffet","med","How should you refill a buffet pan that's running low?","¿Cómo debes rellenar una charola del buffet que se está acabando?",["Swap in a fresh pan — don't pile new food on top of old","Dump new food on top","Stir old and new together","Wait until it's empty for 20 minutes"],["Cambiar por una charola nueva; no echar comida nueva sobre la vieja","Echar la nueva encima","Revolver lo viejo con lo nuevo","Esperar 20 minutos vacía"],"Mixing old and new resets nothing — the old food is still old.","Mezclar lo viejo con lo nuevo no cambia nada; lo viejo sigue siendo viejo.",FC),
("buffet","med","Why keep sneeze guards in place over the buffet?","¿Por qué mantener las protecciones (sneeze guards) sobre el buffet?",["They protect food from coughs, sneezes and hands","For decoration","To keep it warm","To hold signs"],["Protegen la comida de tos, estornudos y manos","Para decorar","Para mantenerla caliente","Para colgar letreros"],"Food on self-service display must be protected from contamination.","La comida de autoservicio debe estar protegida de contaminación.",FC),
("coffee","easy","Why label decaf and regular coffee pots clearly?","¿Por qué rotular bien las jarras de café descafeinado y normal?",["Some guests can't have caffeine for health reasons","For looks only","To use less coffee","Guests can taste the difference anyway"],["Algunos huéspedes no pueden tomar cafeína por salud","Solo por apariencia","Para usar menos café","Los huéspedes notan la diferencia de todos modos"],"Clear labels are a simple way to keep guests safe and happy.","Las etiquetas claras son una forma sencilla de cuidar a los huéspedes.",BP),
("cleaning","easy","When should you clean and sanitize the breakfast tables?","¿Cuándo debes limpiar y desinfectar las mesas del desayuno?",["After each guest leaves, plus at close","Only at close","Once a week","Only if sticky"],["Cada vez que un huésped se va y al cerrar","Solo al cerrar","Una vez a la semana","Solo si están pegajosas"],"Fresh tables are one of the first things guests notice.","Las mesas limpias son de lo primero que notan los huéspedes.",BP),
("pests","med","You see mouse droppings in the breakfast storage room. What do you do?","Ves excremento de ratón en la bodega del desayuno. ¿Qué haces?",["Tell your manager right away and throw out any food that may be contaminated","Sweep it and say nothing","Keep serving","Set food on top"],["Avisar al gerente de inmediato y tirar la comida que pudo contaminarse","Barrerlo y no decir nada","Seguir sirviendo","Poner comida encima"],"Pests carry disease. The hotel needs to call pest control.","Las plagas transmiten enfermedades. El hotel debe llamar a control de plagas.",FC),
]
for t in B: n(BK,*t)
